export type SearchResourcesData = {
    body?: never;
    path?: never;
    query?: {
        /**
         * Text to search in names / content
         */
        query?: string;
        /**
         * Max items per page (1–200, default 50)
         */
        limit?: number;
        /**
         * Opaque cursor from a previous response
         */
        cursor?: string;
        /**
         * Sort dimension: relevance (default) | name | size | updated_at | created_at
         */
        order_by?: string;
        /**
         * Comma-separated: file, folder (both by default)
         */
        resource_types?: string;
        /**
         * Reverse the sort order
         */
        reverse?: boolean;
        /**
         * Filter by file extensions (comma-separated)
         */
        type?: string;
        /**
         * Restrict search to this folder
         */
        folder_id?: string;
        /**
         * Recurse into subfolders (default true)
         */
        recursive?: boolean;
        /**
         * Minimum creation timestamp (unix seconds)
         */
        created_after?: number;
        /**
         * Maximum creation timestamp
         */
        created_before?: number;
        /**
         * Minimum modification timestamp
         */
        modified_after?: number;
        /**
         * Maximum modification timestamp
         */
        modified_before?: number;
        /**
         * Minimum file size (bytes)
         */
        min_size?: number;
        /**
         * Maximum file size (bytes)
         */
        max_size?: number;
    };
    url: '/api/search';
};

export type SearchResourcesErrors = {
    /**
     * Search service unavailable
     */
    503: unknown;
};

export type SearchResourcesResponses = {
    /**
     * Search results (cursor-paginated envelope shared with *resources)
     */
    200: SearchResourcesDto;
};

export type SearchResourcesResponse = SearchResourcesResponses[keyof SearchResourcesResponses];

