export type UploadChunkData = {
    /**
     * Raw chunk bytes
     */
    body?: unknown;
    path: {
        /**
         * Upload session ID
         */
        upload_id: string;
    };
    query: {
        /**
         * Zero-based chunk index
         */
        chunk_index: number;
        /**
         * Optional hex-encoded checksum for integrity verification. Computed incrementally during the streaming write. Algorithm is selected by `checksumalg` (default `md5`). Also accepted via the legacy `Content-MD5` request header.
         */
        checksum?: string;
        /**
         * Algorithm used by `checksum`. One of: `md5` (default, legacy), `sha256` / `sha-256`, `blake3`. Unknown values return 400.
         */
        checksumalg?: string;
    };
    url: '/api/uploads/{upload_id}';
};

export type UploadChunkErrors = {
    /**
     * Invalid chunk, size mismatch, checksum mismatch, or unknown `checksumalg`
     */
    400: unknown;
    /**
     * Upload session not found
     */
    404: unknown;
    /**
     * Chunk exceeds `storage.chunk_max_bytes` cap
     */
    413: unknown;
};

export type UploadChunkResponses = {
    /**
     * Chunk received
     */
    200: ChunkUploadResponseDto;
};

export type UploadChunkResponse = UploadChunkResponses[keyof UploadChunkResponses];

export type CompleteUploadData = {
    /**
     * Optional. End-to-end integrity verification of the assembled file. **`blake3` is highly recommended** as the `checksumalg` value — the server already computes BLAKE3 over the assembled file during hash-on-write assembly, so verification is a string comparison with zero extra CPU/IO. Picking `md5` or `sha256` is supported for legacy client tooling but triggers a second full hash pass over the assembled file. Clients that POST with no body (or with an empty JSON object) get today's behavior: no verification, server returns the BLAKE3 it computed.
     */
    body: CompleteUploadRequest;
    path: {
        /**
         * Upload session ID
         */
        upload_id: string;
    };
    query?: never;
    url: '/api/uploads/{upload_id}/complete';
};

export type CompleteUploadErrors = {
    /**
     * Unknown `checksumalg` or final-checksum mismatch
     */
    400: unknown;
    /**
     * Upload session not found
     */
    404: unknown;
    /**
     * Assembly, hashing, or file creation failed
     */
    500: unknown;
};

export type CompleteUploadResponses = {
    /**
     * File assembled and created
     */
    201: CompleteUploadResponse;
};

export type CompleteUploadResponse2 = CompleteUploadResponses[keyof CompleteUploadResponses];

